head.script:
scwin.onpageload = function() {
    var jsonData = [{
        "col1": "1",
        "col2": "2"
    }, {
        "col1": "3",
        "col2": "4"
    }, {
        "col1": "a",
        "col2": "b"
    }, {
        "col1": "c",
        "col2": "d"
    }];
    dataList1.setJSON(jsonData);
};
scwin.onpageunload = function() {};
scwin.setFormatFunc = function(data, formattedData, rowIndex, colIndex) {
    if (data == "1") {
        //grid1.setCellDisabled(2, "col1", true);
        grid1.setCellReadOnly(3, "col1", true);
        //grid1.setCellColor(0, 0, "red");
        //grid1.setCellBackgroundColor(0, 1, "red");
    } else {
        grid1.setCellDisabled(2, "col1", true);
        //grid1.setCellReadOnly(3, "col1", false);
        //grid1.setCellColor(0, 0, "red");
        //grid1.setCellBackgroundColor(0, 1, "red");
    }
    tem_cnt++;
    localStorage.setItem("log", tem_cnt);
    //alert(localStorage.getItem('log'))
    console.log(scwin.setFormatFunc);
    //console.log(data);
    return formattedData;
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') < 10", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.tem_cnt = 0;
    localStorage.removeItem("log");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
